QLineEdit, QComboBox, QSpinBox, QDoubleSpinBox {
    background-color: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.10);
    border-radius: 3px;
    padding: 4px 6px;
    color: #dddddd;
    font-size: 11px;
}
QLineEdit:focus, QComboBox:focus, QSpinBox:focus, QDoubleSpinBox:focus {
    border: 1px solid rgba(255, 255, 255, 0.25);
    background-color: rgba(255, 255, 255, 0.06);
}
QLineEdit:disabled, QComboBox:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled {
    color: #666666;
    background-color: rgba(255, 255, 255, 0.02);
}
QComboBox::drop-down {
    border: none;
    padding-right: 4px;
}
QListWidget {  background-color: rgba(255, 255, 255, 0.03);  border: 1px solid rgba(255, 255, 255, 0.08);  border-radius: 3px;  padding: 2px;  font-size: 11px;  color: #cccccc;}QListWidget::item {  padding: 3px 6px;  border-radius: 2px;}QListWidget::item:hover {  background-color: rgba(255, 255, 255, 0.06);}QListWidget::item:selected {  background-color: rgba(106, 191, 105, 0.25);  color: #eeeeee;}
QScrollBar:vertical {
    background: transparent; width: 6px;
}
QScrollBar::handle:vertical {
    background: rgba(255, 255, 255, 0.15);
    border-radius: 3px; min-height: 20px;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0px;
}

